import pandas as pd,numpy as np,glob,itertools
from scipy.signal import lfilter
D={f:pd.read_csv(f) for f in sorted(glob.glob('train/*.csv'))}
def filt(x,tau,dt=0.001):
    if tau<=0: return x
    a=np.exp(-dt/tau); return lfilter([1-a],[1,-a],x-x[0])+0*x[0]
def feats(d,t1,t2,t3):
    V=d.voltage_pu.values; th=d.bus_angle_rad.values; Vs=d.voltage_setpoint_pu.values
    w=np.gradient(th,0.001)
    return np.c_[filt(Vs-Vs[0],t1), filt(V-V[0],t2), filt(w,t3)]
best=None
for t1 in [0,0.05,0.2,0.5,1,3]:
  for t2 in [0,0.02,0.05,0.2,1]:
    for t3 in [0.05,0.5]:
        X=[];Y=[]
        for f,d in D.items():
            X.append(feats(d,t1,t2,t3)); Y.append(d.reactive_power_pu.values-d.reactive_power_pu.values[0])
        X=np.vstack(X);Y=np.concatenate(Y)
        c,res,_,_=np.linalg.lstsq(np.c_[X],Y,rcond=None)
        rms=np.sqrt(np.mean((X@c-Y)**2))
        if best is None or rms<best[0]: best=(rms,t1,t2,t3,c)
        print(t1,t2,t3,round(rms,5),np.round(c,3))
print('best',best)
